import{_ as o,M as s,p as c,q as d,R as e,N as a,V as l,t,a1 as i}from"./framework-5866ffd3.js";const h="/assets/nibrs-f85ff4c3.png",u="/assets/edgar-5f87938e.png",m={},g=e("h1",{id:"connections-to-national-level-external-data",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#connections-to-national-level-external-data","aria-hidden":"true"},"#"),t(" Connections to national-level external data")],-1),f={style:{"margin-top":"-0.5em"}},p=e("em",null,"by Scott Daniel • 4 Sep 2026",-1),w=e("h2",{id:"overview",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#overview","aria-hidden":"true"},"#"),t(" Overview")],-1),b={href:"https://okn.us/",target:"_blank",rel:"noopener noreferrer"},y=i('<p>As of this writing, we have integrated two national-level datasets into the SCALES knowledge graph. The first is the 2018–22 set of annual extract files from the FBI&#39;s <strong>National Incident-Based Reporting System (NIBRS)</strong>, maintained by the Inter-university Consortium for Political and Social Research (ICPSR); the second is the set of identifiers from the SEC&#39;s <strong>Electronic Data Gathering, Analysis, and Retrieval (EDGAR)</strong> system that correspond to publicly traded companies appearing as litigants in our PACER dataset, as well as some additional information about those companies.</p><h2 id="data-features" tabindex="-1"><a class="header-anchor" href="#data-features" aria-hidden="true">#</a> Data features</h2><h3 id="nibrs-extract-files" tabindex="-1"><a class="header-anchor" href="#nibrs-extract-files" aria-hidden="true">#</a> NIBRS extract files</h3><div style="margin-top:1em;margin-bottom:1em;text-align:center;"><img src="'+h+'"></div>',4),S=e("li",null,[e("em",null,"Size:"),t(" These files are quite large, given that they aggregate data reported to NIBRS by state and local law enforcement agencies across the whole country; the five years we incorporated into our dataset totaled 21.7m records in the arrestee files and 41.4m in the incident files, from which we generated a set of "),e("strong",null,"404m triples"),t(".")],-1),v=e("em",null,"Shape and origin:",-1),C={href:"https://www.icpsr.umich.edu/web/ICPSR/studies/35158/versions/V2",target:"_blank",rel:"noopener noreferrer"},x=e("li",null,[e("em",null,"Notable coverage:"),e("ul",null,[e("li",null,[t("Geographical data, in the form of Federal Information Processing Standard ("),e("strong",null,"FIPS"),t(") state/county codes for reporting agencies")]),e("li",null,[t("Three-digit "),e("strong",null,"UCR offense codes"),t(" for all applicable arrests")]),e("li",null,[e("strong",null,"NIBRS drug codes"),t(" for drug-related arrests")])])],-1),I=i('<h3 id="edgar-company-data" tabindex="-1"><a class="header-anchor" href="#edgar-company-data" aria-hidden="true">#</a> EDGAR company data</h3><div style="margin-top:1em;margin-bottom:1em;text-align:center;"><img src="'+u+'"></div><ul><li><em>Size:</em> At <strong>24.8k triples</strong>, corresponding to 7.1k SCALES entities matched to SEC companies (100 of which also matched to SUDOKN companies), this dataset is relatively small, albeit connected to our much larger <a href="../pipeline">PACER dataset</a>.</li><li><em>Shape and origin:</em> We matched companies from our dataset of PACER federal court dockets to companies listed with the SEC using simple strict matching rules, queried an SEC API with the Central Index Keys (CIKs) of those companies, and pulled back JSON data containing various company info/filings/classifications, which we stored as a flat CSV before graph import.</li><li><em>Notable coverage:</em><ul><li><strong>CIK numbers</strong> for all companies in the dataset</li><li>Four-digit Standard Industrial Classification (<strong>SIC</strong>) codes for most CIK-matched companies</li><li>Six-digit North American Industry Classification System (<strong>NAICS</strong>) codes, wherever the SIC codes unambiguously translate to NAICS</li></ul></li></ul><h2 id="use-cases" tabindex="-1"><a class="header-anchor" href="#use-cases" aria-hidden="true">#</a> Use cases</h2><h3 id="nibrs-extract-files-1" tabindex="-1"><a class="header-anchor" href="#nibrs-extract-files-1" aria-hidden="true">#</a> NIBRS extract files</h3><ul><li>Given another dataset that can interface with NIBRS (such as <strong>SCALES state-court</strong> case files, which contain geo/UCR data), we can use the federal measures to better understand that dataset, e.g. by comparing agency report rates for certain UCR codes with the rate at which that code is prosecuted or sentenced.</li><li>The sheer size of the NIBRS dataset can provide some insight into the volume and nature of the activities of NIBRS-reporting law-enforcement agencies. For instance, given a UCR offense code, a consumer of the SCALES graph can ask (via MCP, raw SPARQL, etc) which agencies are reporting that code the most, or which cities/counties.</li><li>Because primary data from law enforcement agencies tends to take a shape similar to the NIBRS data, as we discovered via our <strong>Atlanta PD arrests</strong> dataset, we can quantify the rate of data-practices drift between the FBI and local agencies by measuring the rate of disagreement between the NIBRS data and any corresponding local data.</li></ul><h3 id="edgar-company-data-1" tabindex="-1"><a class="header-anchor" href="#edgar-company-data-1" aria-hidden="true">#</a> EDGAR company data</h3><ul><li>Our integration of SIC/NAICS codes into the SCALES graph means that any data connected to those codes can be aggregated in any way that SIC/NAICS allow. For example, a researcher interested in companies sued for health violations in federal court could break down various <strong>PACER</strong> measures (e.g. length, speed, outcome) according to the SIC/NAICS code of the defendant company.</li><li>Because knowledge graphs have many industrial applications (supply-chain management, resource allocation, infrastructure maintenance, etc), we expect that our EDGAR dataset shares entities with existing corporate knowledge graphs; one such graph is Arizona State University&#39;s <strong>Supply and Demand Open Knowledge Network (SUDOKN),</strong> which is a part of the NSF OKN and is focused on small-to-medium-size manufacturers. Our desire to create a SCALES-SUDOKN interface played into our decision to add EDGAR triples to the SCALES graph, and the connection between these two knowledge networks yields some interesting potential comparisons, e.g. How often are manufacturers in certain cities/states involved in lawsuits? How litigious are companies with certain manufacturing capacities?</li></ul><h2 id="caveats" tabindex="-1"><a class="header-anchor" href="#caveats" aria-hidden="true">#</a> Caveats</h2><h3 id="nibrs-extract-files-2" tabindex="-1"><a class="header-anchor" href="#nibrs-extract-files-2" aria-hidden="true">#</a> NIBRS extract files</h3><ul><li><p>Some agencies in the ICPSR dataset appear to generate a separate arrest number for each arrestee even when multiple arrestees were arrested at once (based on the fact that those agencies didn&#39;t record any multi-arrestee arrest numbers), so in the incident-arrest-arrestee hierarchy, the arrest/arrestee distinction is only accurate insofar as the underlying agencies are accurately making that distinction, meaning e.g. we may overcount arrests if we take the agencies at their word that &quot;new arrest number&quot; implies &quot;new real-world arrest.&quot; Relatedly, some agencies seem to use the arrestee sequence number as an ordinal arrestee index across a set of arrestee-specific arrest numbers rather than within a multi-arrestee arrest number, but this is less consequential given that the arrestee indices are still unique.</p></li><li><p>Many values in the &quot;arrest transaction number&quot; column are missing from the ICPSR data; specifically, the value &quot;-8&quot; appears in that column for 46.7% of the test subset of the 2022 arrests file and 66.2% of the first of three such columns in the &#39;22 incidents subset. This may be an ostensible safeguard against de-anonymization (based on the comment &quot;NA LT 3 values&quot; in the codebook) or a result of bad record-keeping (based on the fact that the second and third such columns in the incidents subset are almost entirely &quot;-8,&quot; suggesting that someone is using that value as a generic missing-data code). Regardless, by adding incident-related triples from the arrestee files rather than the incident files when an arrestee is de-identified from their incident, we&#39;re able to ameliorate this issue and avoid miscounts.</p></li></ul><h3 id="edgar-company-data-2" tabindex="-1"><a class="header-anchor" href="#edgar-company-data-2" aria-hidden="true">#</a> EDGAR company data</h3><ul><li>At present, the confidence-score model for the SCALES-SUDOKN crosswalk is a Fellegi-Sunter-style function with weights trained on 50 human-validated true/false matches, but it&#39;s simple enough that it&#39;s essentially a decision tree whose branching points involve boolean variables pertaining to match exactness, string length, number of tokens, uniqueness in the name set, and word commonness. As a result, our crosswalk likely contains a handful of false positives. (While we would have liked to produce a larger validation set, any substantive attempt at ground-truth annotations for these company matches tends to become a prohibitively time-consuming process, wherein a human searched for addresses/aliases/etc in Recap documents on the one hand and contact info from the company website on the other.)</li></ul>',13);function _(R,A){const r=s("font"),n=s("ExternalLinkIcon");return c(),d("div",null,[g,e("div",f,[a(r,{size:"2"},{default:l(()=>[p]),_:1})]),w,e("p",null,[t("SCALES's vision of an open justice data ecosystem encompasses not only accessible, queryable records from primary data providers like courts and law enforcement agencies, but also secondary resources that provide additional context and research value. Our interest in linking external datasources also stems from our participation in the NSF's "),e("a",b,[t("Open Knowledge Network (OKN)"),a(n)]),t(" project, whose mission is the interweaving of data across subject-matter domains in order to better understand the overarching systems and processes at work in those domains.")]),y,e("ul",null,[S,e("li",null,[v,t(" The ICPSR offers straightforward tabular data, divided into six overlapping files according to the kind of record occupying each row; we found that the Arrestee and Incident files contained the vast majority of interesting data, and we discarded the rest. We also pulled in a Law Enforcement Agency Identifiers (LEAIC) "),e("a",C,[t("crosswalk file"),a(n)]),t(" to translate originating agency identifiers (ORIs) to human-readable agency names.")]),x]),I])}const k=o(m,[["render",_],["__file","index.html.vue"]]);export{k as default};
